package com.poi.investment.bond;
import jakarta.validation.Valid; import jakarta.validation.constraints.*; import java.math.BigDecimal; import java.util.List; import org.springframework.http.*; import org.springframework.web.bind.annotation.*;
@RestController @RequestMapping("/api/v1/bonds") public class BondController {private final BondRepository bonds;public BondController(BondRepository bonds){this.bonds=bonds;}@GetMapping List<Bond> all(){return bonds.findAll();}@PostMapping ResponseEntity<Bond> create(@Valid @RequestBody BondRequest b){if(bonds.existsById(b.isin()))return ResponseEntity.status(HttpStatus.CONFLICT).build();return ResponseEntity.status(HttpStatus.CREATED).body(bonds.save(new Bond(b.isin(),b.issuer(),b.couponRate(),b.marketPrice(),b.rating())));}public record BondRequest(@NotBlank @Size(min=12,max=12)String isin,@NotBlank String issuer,@DecimalMin("0.0")BigDecimal couponRate,@DecimalMin("0.0")BigDecimal marketPrice,String rating){}}
